function idealArrays(n, maxValue) {
  const MOD = 1000000007n;
  const ways = [1n];
  for (let e = 1; e <= 13; e++) {
    ways.push(ways[e - 1] * BigInt(n - 1 + e) / BigInt(e));
  }
  let total = 0n;
  for (let value = 1; value <= maxValue; value++) {
    let count = 1n;
    let rest = value;
    for (let p = 2; p * p <= rest; p++) {
      let e = 0;
      while (rest % p === 0) {
        rest /= p;
        e++;
      }
      if (e > 0) {
        count = count * ways[e] % MOD;
      }
    }
    if (rest > 1) {
      count = count * ways[1] % MOD;
    }
    total = (total + count) % MOD;
  }
  return Number(total);
}

