function idealArrays(n, maxValue) {
  const MOD = 1e9 + 7;
  // count[v]: ideal arrays of the current length that end with v. Grow the length one step at a time:
  // a value d can be followed by any multiple m of d.
  let count = new Array(maxValue + 1).fill(1);
  count[0] = 0;
  for (let length = 2; length <= n; length++) {
    const next = new Array(maxValue + 1).fill(0);
    for (let d = 1; d <= maxValue; d++)
      for (let m = d; m <= maxValue; m += d) next[m] = (next[m] + count[d]) % MOD;
    count = next;
  }
  return count.reduce((sum, c) => (sum + c) % MOD, 0);
}

